import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "./manageUserAccounts.css";
import AdminSidebar from "../components/AdminSideBar";
import Navbar from "../components/navbar";
import Footer from "../components/footer";

function ManageUserAccounts() {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [role, setRole] = useState("");
  const [registrationNumber, setRegistrationNumber] = useState("");
  const [password, setPassword] = useState("");

  const [students, setStudents] = useState([]);
  const [supervisors, setSupervisors] = useState([]);
  const [evaluators, setEvaluators] = useState([]);

  const [editingUserId, setEditingUserId] = useState(null);
  const [viewRole, setViewRole] = useState("Student");

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    const usersRes = await fetch("http://localhost:5000/api/user");
    const users = await usersRes.json();

    const studentsRes = await fetch("http://localhost:5000/api/student");
    const studentsData = await studentsRes.json();

    const facultyRes = await fetch("http://localhost:5000/api/facultyadvisor");
    const facultyData = await facultyRes.json();

    const evaluatorsRes = await fetch("http://localhost:5000/api/evaluator");
    const evaluatorsData = await evaluatorsRes.json();

    const studentList = studentsData.map((student) => {
      const user = users.find((u) => u._id === student.userId);
      return {
        ...user,
        name: student.studentName,
        registrationNumber: student.regNo,
        role: "Student",
        studentId: student._id,
        isGrouped: student.isGrouped
      };
    });

    const supervisorList = facultyData.map((fac) => {
      const user = users.find((u) => u._id === fac.userId);
      return {
        ...user,
        name: fac.Name,
        role: "Supervisor",
        supervisorId: fac._id
      };
    });

    const evaluatorList = evaluatorsData.map((eva) => {
      const user = users.find((u) => u._id === eva.userId);
      return {
        ...user,
        name: eva.Name,
        role: "Evaluator",
        evaluatorId: eva._id
      };
    });

    setStudents(studentList);
    setSupervisors(supervisorList);
    setEvaluators(evaluatorList);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!name || !email || !password || !role) return;

    const userPayload = { username: name, email, password, role };

    let userId;
    if (!editingUserId) {
      const res = await fetch("http://localhost:5000/api/user", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(userPayload),
      });
      const data = await res.json();
      userId = data._id;
    } else {
      await fetch(`http://localhost:5000/api/user/${editingUserId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(userPayload),
      });
      userId = editingUserId;
    }

    if (role === "Student") {
      const studentPayload = {
        userId,
        studentName: name,
        regNo: registrationNumber,
        isGrouped: false,
      };

      await fetch(`http://localhost:5000/api/student${editingUserId ? `/${editingUserId}` : ""}`, {
        method: editingUserId ? "PUT" : "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(studentPayload),
      });
    } else if (role === "Supervisor") {
      const supervisorPayload = { userId, Name: name };
      await fetch(`http://localhost:5000/api/facultyadvisor${editingUserId ? `/${editingUserId}` : ""}`, {
        method: editingUserId ? "PUT" : "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(supervisorPayload),
      });
    } else if (role === "Evaluator") {
      const evaluatorPayload = { userId, Name: name };
      await fetch(`http://localhost:5000/api/evaluator${editingUserId ? `/${editingUserId}` : ""}`, {
        method: editingUserId ? "PUT" : "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(evaluatorPayload),
      });
    }

    await fetchUsers();
    resetForm();
  };

  const handleEdit = (user) => {
    setName(user.name);
    setEmail(user.email);
    setRole(user.role);
    setPassword(user.password);
    setRegistrationNumber(user.registrationNumber || "");
    setEditingUserId(user._id);
  };

  const handleResetPassword = async (userId) => {
    const newPassword = prompt("Enter new password:");
    if (newPassword) {
      await fetch(`http://localhost:5000/api/user/${userId}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ password: newPassword }),
      });
      alert("Password updated.");
    }
  };

  const handleDeleteUser = async (user) => {
    if (!window.confirm("Are you sure you want to delete this user?")) return;

    // Delete subdocument first
    if (user.role === "Student") {
      await fetch(`http://localhost:5000/api/student/${user.studentId}`, {
        method: "DELETE",
      });
    } else if (user.role === "Supervisor") {
      await fetch(`http://localhost:5000/api/facultyadvisor/${user.supervisorId}`, {
        method: "DELETE",
      });
    } else if (user.role === "Evaluator") {
      await fetch(`http://localhost:5000/api/evaluator/${user.evaluatorId}`, {
        method: "DELETE",
      });
    }

    // Delete main user
    await fetch(`http://localhost:5000/api/user/${user._id}`, {
      method: "DELETE",
    });

    await fetchUsers();
  };

  const resetForm = () => {
    setName("");
    setEmail("");
    setRole("");
    setPassword("");
    setRegistrationNumber("");
    setEditingUserId(null);
  };

  const usersToDisplay = {
    Student: students,
    Supervisor: supervisors,
    Evaluator: evaluators,
  }[viewRole];

  return (
    <div className="manage-user-accounts">
      <Navbar />
      <div className="content-wrapper">
        <AdminSidebar />
        <div className="main-content">
          <h1>Manage User Accounts</h1>

          <form onSubmit={handleSubmit} className="user-form">
            <label>Name</label>
            <input value={name} onChange={(e) => setName(e.target.value)} required />

            <label>Email</label>
            <input value={email} onChange={(e) => setEmail(e.target.value)} required type="email" />

            <label>Password</label>
            <input value={password} onChange={(e) => setPassword(e.target.value)} required type="password" />

            <label>Role</label>
            <select value={role} onChange={(e) => setRole(e.target.value)} required>
              <option value="">Select Role</option>
              <option value="Student">Student</option>
              <option value="Supervisor">Supervisor</option>
              <option value="Evaluator">Evaluator</option>
            </select>

            {role === "Student" && (
              <>
                <label>Registration Number</label>
                <input
                  value={registrationNumber}
                  onChange={(e) => setRegistrationNumber(e.target.value)}
                  required
                />
              </>
            )}

            <button type="submit">{editingUserId ? "Update" : "Add"} User</button>
          </form>

          <div className="role-switcher">
            <button onClick={() => setViewRole("Student")}>View Students</button>
            <button onClick={() => setViewRole("Supervisor")}>View Supervisors</button>
            <button onClick={() => setViewRole("Evaluator")}>View Evaluators</button>
          </div>

          <table>
            <thead>
              <tr>
                <th>Name</th>
                <th>Email</th>
                {viewRole === "Student" && <th>Reg. No</th>}
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {usersToDisplay.map((user, i) => (
                <tr key={i}>
                  <td>{user.name}</td>
                  <td>{user.email}</td>
                  {viewRole === "Student" && <td>{user.registrationNumber}</td>}
                  <td>
                    <button onClick={() => handleEdit(user)}>Edit</button>
                    <button onClick={() => handleResetPassword(user._id)}>Reset Password</button>
                    <button onClick={() => handleDeleteUser(user)}>Delete</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
      <Footer />
    </div>
  );
}

export default ManageUserAccounts;
